import {Arkanoid,POWER,WIDTH,HEIGHT,PADDLE_Y,clamp} from './engine.js';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');canvas.width=WIDTH;canvas.height=HEIGHT;
const palette={1:'#bc9be7',2:'#81b8ec',3:'#8bceb1',4:'#e7d380',5:'#edaa8b',6:'#d58fb7',S:'#b3bdd9',G:'#cbb168'};
let best=0;try{best=Number(localStorage.getItem('c64-arkanoid-best'))||0;}catch{}
let audio=null,sound=false,keys=new Set(),held=new Set(),target,dragId=null,downX=0,downTime=0,particles=[],popups=[],noticeTime=0,last=performance.now(),accumulator=0;
function unlock(){if(!audio){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio)audio=new Audio();}if(audio?.state==='suspended')audio.resume().catch(()=>{});}
function note(freq,duration=.06,type='square',volume=.025){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(40,freq*.7),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function fanfare(){note(440,.12,'triangle');if(sound&&audio){const t=audio.currentTime;for(const [i,f]of [554,659,880].entries()){const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.035,t+(i+1)*.11);g.gain.exponentialRampToValueAtTime(.001,t+(i+2)*.15);o.connect(g);g.connect(audio.destination);o.start(t+(i+1)*.11);o.stop(t+(i+2)*.15);}}}
function explode(x,y,color,n=10){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*110,vy:(Math.random()-.5)*100,life:.5,color});}
function tell(text,seconds=1.5){$('notice').textContent=text;noticeTime=performance.now()+seconds*1000;}
function clearInput(){keys.clear();held.clear();target=undefined;dragId=null;document.querySelectorAll('.held').forEach(e=>e.classList.remove('held'));}
function save(){if(game.score>best){best=game.score;try{localStorage.setItem('c64-arkanoid-best',String(best));}catch{}}}
function overlay(kicker,title,text,button){$('overline').textContent=kicker;$('overlayTitle').textContent=title;$('overlayText').innerHTML=text;$('start').textContent=button;$('overlay').hidden=false;}
const game=new Arkanoid({event:(type,data)=>{switch(type){case 'brick':explode(data.x,data.y,palette[data.type]);note(data.type==='S'?780:420+Number(data.type||0)*55,.055);break;case 'metal':explode(data.x,data.y,'#d9e2ff',4);note(170,.04,'triangle');break;case 'paddle':note(270,.04);break;case 'wall':note(140,.018,'triangle',.012);break;case 'launch':note(650,.08,'triangle');break;case 'laser':note(1000,.055,'sawtooth',.015);break;case 'round':tell(data===9?'THE GUARDIAN':`ROUND ${String(data).padStart(2,'0')}`);break;case 'power':fanfare();tell(POWER[data].name,1);popups.push({x:game.paddle.x,y:PADDLE_Y-20,text:POWER[data].name,life:1.2,color:POWER[data].color});break;case 'clear':fanfare();save();tell(game.round===9?'GUARDIAN DEFEATED':'ROUND CLEAR');break;case 'boss':explode(data.x,data.y,'#ce9bdc',5);note(100,.09,'sawtooth');break;case 'enemy':explode(data.x,data.y,'#86d9d1');note(350,.08);break;case 'life':tell('EXTRA SHIP');fanfare();break;case 'lost':explode(game.paddle.x,PADDLE_Y,'#ee94b1',22);note(110,.4,'sawtooth',.04);save();break;case 'over':clearInput();save();$('pause').disabled=true;overlay('SIGNAL LOST','GAME OVER',`Final score: ${String(game.score).padStart(6,'0')}<br>You reached round ${game.round} of 9. One more try?`,'PLAY AGAIN ▶');break;case 'won':clearInput();save();$('pause').disabled=true;overlay('MISSION COMPLETE','THE WALL IS HISTORY.',`All nine rounds conquered.<br>Final score: ${String(game.score).padStart(6,'0')}`,'PLAY AGAIN ▶');fanfare();break;}}});
function pause(force=false){if(game.mode==='playing'){game.pause();clearInput();save();overlay('PAUSED','HOLD THAT THOUGHT.','Your mission is safe.<br>Resume when you’re ready.','RESUME GAME ▶');$('pause').textContent='▶';$('pause').setAttribute('aria-label','Resume game');}else if(!force&&game.mode==='paused'){game.resume();$('overlay').hidden=true;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');last=performance.now();accumulator=0;}}
$('start').onclick=()=>{unlock();clearInput();if(game.mode==='paused'){pause();return;}particles=[];popups=[];game.start();$('overlay').hidden=true;$('pause').disabled=false;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');last=performance.now();accumulator=0;};$('pause').onclick=()=>pause();$('sound').onclick=()=>{unlock();sound=!sound;$('sound').textContent=sound?'SOUND ON':'SOUND OFF';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');note(660,.1,'triangle');};
for(const id of ['left','right','action']){const el=$(id);el.onpointerdown=e=>{e.preventDefault();unlock();el.setPointerCapture(e.pointerId);held.add(id);el.classList.add('held');if(id==='action')game.action();};const release=()=>{held.delete(id);el.classList.remove('held');};el.onpointerup=release;el.onpointercancel=release;el.onlostpointercapture=release;}
$('action').addEventListener('click',e=>{if(e.detail===0){unlock();game.action();}});
function worldX(clientX){const r=canvas.getBoundingClientRect(),width=Math.min(r.width,r.height*WIDTH/HEIGHT);return clamp((clientX-r.left-(r.width-width)/2)/width*WIDTH,0,WIDTH);}
canvas.onpointerdown=e=>{if(game.mode!=='playing')return;e.preventDefault();unlock();canvas.setPointerCapture(e.pointerId);dragId=e.pointerId;downX=e.clientX;downTime=performance.now();target=worldX(e.clientX);};canvas.onpointermove=e=>{if(e.pointerId===dragId)target=worldX(e.clientX);};canvas.onpointerup=e=>{if(e.pointerId!==dragId)return;if(Math.abs(e.clientX-downX)<10&&performance.now()-downTime<350)game.action();dragId=null;};canvas.onpointercancel=()=>{dragId=null;target=undefined;};canvas.onlostpointercapture=()=>{dragId=null;};
canvas.onmousemove=e=>{if(e.buttons===0&&e.pointerType!=='touch'&&matchMedia('(pointer:fine)').matches)target=worldX(e.clientX);};
window.addEventListener('keydown',e=>{if(!['arrowleft','arrowright','a','d',' ','p','escape'].includes(e.key.toLowerCase()))return;if(e.target instanceof HTMLButtonElement&&e.target.offsetParent!==null&&(e.key===' '||e.key==='Enter'))return;e.preventDefault();const k=e.key.toLowerCase();if(!e.repeat&&(k==='p'||k==='escape'))pause();keys.add(k);if(k===' '){unlock();game.action();}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>pause(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);});window.addEventListener('pagehide',save);
const text=(value,x,y,color='#e1e4ff',size=8,align='left')=>{ctx.fillStyle=color;ctx.font=`bold ${size}px monospace`;ctx.textAlign=align;ctx.fillText(value,x,y);};
function brick(b){const color=palette[b.type];ctx.fillStyle='#050715';ctx.fillRect(b.x+1,b.y+2,b.w,b.h);ctx.fillStyle=color;ctx.fillRect(b.x,b.y,b.w,b.h-1);ctx.fillStyle='#ffffff55';ctx.fillRect(b.x,b.y,b.w,2);ctx.fillRect(b.x,b.y,2,b.h-1);ctx.fillStyle='#00000035';ctx.fillRect(b.x,b.y+b.h-3,b.w,2);ctx.fillRect(b.x+b.w-2,b.y+2,2,b.h-3);if(b.type==='S'&&b.hp===1){ctx.strokeStyle='#4d5277';ctx.beginPath();ctx.moveTo(b.x+10,b.y);ctx.lineTo(b.x+13,b.y+5);ctx.lineTo(b.x+9,b.y+9);ctx.stroke();}if(b.type==='G'){ctx.fillStyle='#f8e9a8';ctx.fillRect(b.x+12,b.y+3,4,3);}}
function draw(){ctx.fillStyle='#15132c';ctx.fillRect(0,0,WIDTH,HEIGHT);ctx.fillStyle='#1b1935';for(let x=16;x<310;x+=20)for(let y=18;y<440;y+=20){ctx.fillRect(x,y,1,1);ctx.fillRect(x+9,y+9,1,1);}ctx.fillStyle='#2b254b';for(let y=0;y<HEIGHT;y+=22){ctx.fillRect(0,y,8,19);ctx.fillRect(312,y,8,19);ctx.fillStyle='#685a89';ctx.fillRect(1,y,2,18);ctx.fillRect(313,y,2,18);ctx.fillStyle='#2b254b';}ctx.fillStyle='#78659f';ctx.fillRect(0,0,320,7);ctx.fillStyle='#aea0c9';ctx.fillRect(0,0,320,2);ctx.fillStyle='#0b0b20';ctx.fillRect(23,7,25,5);ctx.fillRect(272,7,25,5);
 for(const b of game.bricks)if(b.alive)brick(b);
 if(game.boss){const b=game.boss;ctx.fillStyle=b.flash>0?'#e9d5ff':'#806199';ctx.fillRect(b.x,b.y+8,b.w,b.h-8);ctx.fillRect(b.x+8,b.y,b.w-16,b.h);ctx.fillStyle='#b596c5';ctx.fillRect(b.x+8,b.y+5,b.w-16,5);ctx.fillStyle='#40304f';ctx.fillRect(b.x+13,b.y+21,13,9);ctx.fillRect(b.x+39,b.y+21,13,9);ctx.fillRect(b.x+27,b.y+28,10,12);ctx.fillRect(b.x+17,b.y+46,30,5);ctx.fillStyle='#f7acc5';ctx.fillRect(b.x+17,b.y+24,6,3);ctx.fillRect(b.x+42,b.y+24,6,3);text('GUARDIAN',160,29,'#b19acd',8,'center');ctx.fillStyle='#372947';ctx.fillRect(80,34,160,3);ctx.fillStyle='#d09bce';ctx.fillRect(80,34,160*Math.max(0,b.hp)/b.maxHp,3);}
 for(const e of game.enemies){ctx.fillStyle='#9bdacb';ctx.fillRect(e.x-4,e.y-5,8,10);ctx.fillRect(e.x-6,e.y-2,12,4);ctx.fillStyle='#264346';ctx.fillRect(e.x-2,e.y-2,4,4);}
 for(const c of game.capsules){ctx.fillStyle='#0c0d20';ctx.fillRect(c.x-9,c.y-5,19,12);ctx.fillStyle=POWER[c.type].color;ctx.fillRect(c.x-8,c.y-5,16,10);ctx.fillStyle='#ffffff44';ctx.fillRect(c.x-7,c.y-5,14,2);text(c.type,c.x,c.y+3,'#1a1533',9,'center');}
 for(const shot of game.shots){ctx.fillStyle='#f3a0b9';ctx.fillRect(shot.x-1,shot.y-6,2,7);ctx.fillStyle='#fff0ed';ctx.fillRect(shot.x,shot.y-6,1,3);}
 const p=game.paddle,px=Math.round(p.x-p.w/2);ctx.fillStyle='#625d91';ctx.fillRect(px,PADDLE_Y+2,p.w,6);ctx.fillStyle=game.effect==='C'?'#8ed8b0':'#afb9df';ctx.fillRect(px+5,PADDLE_Y,p.w-10,5);ctx.fillStyle='#e2e4fa';ctx.fillRect(px+5,PADDLE_Y,p.w-10,2);ctx.fillStyle=game.effect==='L'?'#ffb2b7':'#d38ba8';ctx.fillRect(px,PADDLE_Y-2,5,10);ctx.fillRect(px+p.w-5,PADDLE_Y-2,5,10);ctx.fillStyle='#954f7c';ctx.fillRect(px,PADDLE_Y+6,5,2);ctx.fillRect(px+p.w-5,PADDLE_Y+6,5,2);
 for(const b of game.balls){ctx.fillStyle='#e1deae55';ctx.fillRect(b.x-b.vx*.016-2,b.y-b.vy*.016-2,4,4);ctx.fillStyle='#fff5ca';ctx.fillRect(Math.round(b.x)-2,Math.round(b.y)-3,4,6);ctx.fillRect(Math.round(b.x)-3,Math.round(b.y)-2,6,4);ctx.fillStyle='#fffdf4';ctx.fillRect(Math.round(b.x)-2,Math.round(b.y)-2,2,2);}
 if(game.balls.some(b=>b.attached)&&game.mode==='playing'&&!game.transition){text('TAP / SPACE TO LAUNCH',160,387,'#aaa4c6',7,'center');}
 if(game.exit){ctx.fillStyle=Math.floor(game.time*6)%2?'#b6a0ed':'#6b548d';ctx.fillRect(311,392,9,36);text('EXIT',283,403,'#c5a2ff',7);}
 for(const f of particles){ctx.fillStyle=f.color;ctx.globalAlpha=Math.max(0,f.life*2);ctx.fillRect(Math.round(f.x),Math.round(f.y),2,2);}ctx.globalAlpha=1;for(const p of popups)text(p.text,p.x,p.y,p.color,7,'center');
 ctx.fillStyle='#6d5b8f';ctx.fillRect(10,434,300,1);
}
function updateHud(){save();$('score').textContent=String(game.score).padStart(6,'0');$('best').textContent=String(best).padStart(6,'0');$('round').textContent=`${String(game.round).padStart(2,'0')} / 09`;$('lives').textContent=game.lives<=4?Array(Math.max(0,game.lives)).fill('▰').join(' ')||'—':`▰ × ${game.lives}`;$('lives').setAttribute('aria-label',`${game.lives} ships`);const waiting=game.balls.some(b=>b.attached);$('action').textContent=waiting?'LAUNCH ↗':game.effect==='L'?'FIRE ◎':'LAUNCH ↗';$('mode').textContent=game.exit?'EXIT OPEN → MOVE RIGHT':game.effect?`${POWER[game.effect].name} · ${Math.ceil(game.effectTime)}s`:game.balls.length>1?`${game.balls.length} BALLS IN PLAY`:'VAUS SYSTEMS READY';const n=game.bricks.filter(b=>b.alive&&b.type!=='G').length;$('remaining').textContent=game.round===9?`GUARDIAN ${Math.max(0,game.boss?.hp||0)} / 32`:`${n} BRICKS REMAIN`;}
let hudTime=0;
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000);last=now;if(game.mode==='playing'){accumulator+=dt;const move=Number(keys.has('arrowright')||keys.has('d')||held.has('right'))-Number(keys.has('arrowleft')||keys.has('a')||held.has('left'));if(move)target=undefined;while(accumulator>=1/120){game.step(1/120,{move,target,action:keys.has(' ')||held.has('action')});accumulator-=1/120;}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=80*dt;p.life-=dt;}for(const p of popups){p.y-=20*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);popups=popups.filter(p=>p.life>0);}else accumulator=0;if(now>noticeTime)$('notice').textContent='';if(now-hudTime>80){updateHud();hudTime=now;}draw();}
updateHud();requestAnimationFrame(frame);
